. token_urlsafe ( 64 ) # Create code_challenge by hashing the verifier with SHA256 code_challenge = base64 . urlsafe_b64encode ( hashlib . sha256 ( code_verifier . encode ( ) ) . digest ( ) ) . rstrip ( b&#x27;=&#x27; ) . decode ( ) # Store code_verifier securely - you&#x27;ll need it for the token exchange import base64 import hashlib import secrets # Generate a random code_verifier (43-128 URL-safe characters) code_verifier = secrets . token_urlsafe ( 64 ) # Create code_challenge by hashing the verifier with SHA256 code_challenge = base64 . urlsafe_b64encode ( hashlib . sha256 ( code_verifier . encode ( ) ) . digest ( ) ) . rstrip ( b&#x27;=&#x27; ) . decode ( ) # Store code_verifier securely - you&#x27;ll need it for the token exchange Error Handling Status Code Meaning Action 401 Token expired or revoked Refresh the token, or prompt user to reconnect 403 Insufficient permissions Request additional scopes or handle gracefully Example Implementation Python Copied import base64 import hashlib import secrets import requests from flask import Flask , redirect , request , session app = Flask ( __name__ ) app . secret_key = &#x27;your-secret-key&#x27; CLIENT_ID = &#x27;your-client-id&#x27; CLIENT_SECRET = &#x27;your-client-secret&#x27; REDIRECT_URI = &#x27;https://your-app.com/callback&#x27; TOKEN_URL = &#x27;https://sentry.io/oauth/token/&#x27; def generate_pkce_pair ( ) : &quot;&quot;&quot;Generate a code verifier and challenge for PKCE.&quot;&quot;&quot; code_verifier = secrets . token_urlsafe ( 64 ) code_challenge = base64 . urlsafe_b64encode ( hashlib . sha256 ( code_verifier . encode ( ) ) . digest ( ) ) . rstrip ( b&#x27;=&#x27; ) . decode ( ) return code_verifier , code_challenge @app . route ( &#x27;/connect&#x27; ) def connect ( ) : code_verifier , code_challenge = generate_pkce_pair ( ) session [ &#x27;code_verifier&#x27; ] = code_verifier return redirect ( f&quot;https://sentry.io/oauth/authorize/&quot; f&quot;?client_id= { CLIENT_ID } &quot; f&quot;&amp;response_type=code&quot; f&quot;&amp;scope=org:read%20project:read&quot; f&quot;&amp;redirect_uri= { REDIRECT_URI } &quot; f&quot;&amp;code_challenge= { code_challenge } &quot; f&quot;&amp;code_challenge_method=S256&quot; ) @app . route ( &#x27;/callback&#x27; ) def callback ( ) : code = request . args . get ( &#x27;code&#x27; ) code_verifier = session . pop ( &#x27;code_verifier&#x27; , None ) response = requests . post ( TOKEN_URL , data = { &quot;client_id&quot; : CLIENT_ID , &quot;client_secret&quot; : CLIENT_SECRET , &quot;grant_type&quot; : &quot;authorization_code&quot; , &quot;code&quot; : code , &quot;code_verifier&quot; : code_verifier } ) tokens = response . json ( ) session [ &#x27;access_token&#x27; ] = tokens [ &#x27;access_token&#x27; ] session [ &#x27;refresh_token&#x27; ] = tokens [ &#x27;refresh_token&#x27; ] return &quot;Connected!&quot; def refresh_token ( ) : response = requests . post ( TOKEN_URL , data = { &quot;client_id&quot; : CLIENT_ID , &quot;client_secret&quot; : CLIENT_SECRET , &quot;grant_type&quot; : &quot;refresh_token&quot; , &quot;refresh_token&quot; : session [ &#x27;refresh_token&#x27; ] } ) tokens = response . json ( ) session [ &#x27;access_token&#x27; ] = tokens [ &#x27;access_token&#x27; ] session [ &#x27;refresh_token&#x27; ] = tokens [ &#x27;refresh_token&#x27; ] import base64 import hashlib import secrets import requests from flask import Flask , redirect , request , session app = Flask ( __name__ ) app . secret_key = &#x27;your-secret-key&#x27; CLIENT_ID = &#x27;your-client-id&#x27; CLIENT_SECRET = &#x27;your-client-secret&#x27; REDIRECT_URI = &#x27;https://your-app.com/callback&#x27; TOKEN_URL = &#x27;https://sentry.io/oauth/token/&#x27; def generate_pkce_pair ( ) : &quot;&quot;&quot;Generate a code verifier and challenge for PKCE.&quot;&quot;&quot; code_verifier = secrets . token_urlsafe ( 64 ) code_challenge = base64 . urlsafe_b64encode ( hashlib . sha256 ( code_verifier . encode ( ) ) . digest ( ) ) . rstrip ( b&#x27;=&